func render(name string, fields []Field) string {
	var b strings.Builder
	fmt.Fprintf(&b, "type %s struct {\n", name)
	for _, f := range fields {
		fmt.Fprintf(&b, "\t%s %s", f.Name, f.Type)
		if f.Tag != "" {
			fmt.Fprintf(&b, " `json:%q`", f.Tag)
		}
		b.WriteByte('\n')
	}
	b.WriteString("}\n")
	return gofmt(b.String())
}
